<?php
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Business,Ctx,Db,Jalali,Money,Request};
use Agah\Erp\Modules\Files\FileService;
use Agah\Erp\Modules\Payroll\PayrollService;
use Agah\Erp\Modules\Assets\AssetService;
if(!defined('ABSPATH'))exit;
$a=AssetService::get($cid,Request::int('get','id'));$eid=(int)$a['id'];
?>
<section class="erp-card"><h2><?php echo esc_html($a['code'].' — '.$a['name']); ?></h2><p><?php echo esc_html('خرید: '.Jalali::format($a['acquired_date']).' | بهره‌برداری: '.Jalali::format($a['start_date']).' | '.['active'=>'فعال','disposed'=>'واگذارشده','void'=>'باطل'][$a['status']]); ?></p><dl class="erp-stats"><?php foreach(['cost'=>'بهای خرید','accum'=>'استهلاک انباشته','book_value'=>'ارزش دفتری پیش از واگذاری','residual'=>'ارزش اسقاط'] as $k=>$l): ?><div><dt><?php echo esc_html($l); ?></dt><dd><?php echo esc_html(Money::fmt((int)$a[$k],Ctx::unit())); ?></dd></div><?php endforeach; ?></dl><div class="erp-scroll"><table class="erp-table"><thead><tr><th>رویداد</th><th>تاریخ</th><th>مبلغ</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($a['events'] as $e): ?><tr><td><?php echo esc_html(['purchase'=>'خرید','depreciation'=>'استهلاک','disposal'=>'واگذاری'][$e['kind']]); ?></td><td><?php echo esc_html(Jalali::format($e['doc_date'])); ?></td><td><?php echo esc_html(Money::fmt((int)$e['amount'],Ctx::unit())); ?><?php if($e['kind']==='disposal'){$s=json_decode($e['snapshot'],true);echo '<br>'.esc_html('عواید: '.Money::fmt((int)$e['proceeds'],Ctx::unit()).' | سود / زیان: '.Money::fmt((int)$s['gain'],Ctx::unit()));} ?></td><td><?php echo $e['status']==='issued'?'صادرشده':'باطل'; ?></td><td><?php if(Ctx::can('voucher.view')&&$e['voucher_id']): ?><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'voucher_view','id'=>$e['voucher_id']])); ?>">سند</a><?php endif; ?><?php if(Ctx::can('asset.delete')&&$e['status']==='issued'): ?><form method="post"><?php self::form('module_asset_void',$cid,$p,$e['id']);self::input('reason','دلیل ابطال','','text','required minlength="5"'); ?><button type="submit" class="btn btn-outline">ابطال رویداد</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($a['status']==='active'&&Ctx::can('asset.approve')): ?><section class="erp-card"><h3>استهلاک یک ماه</h3><form method="post" class="erp-form"><?php self::form('module_asset_depreciate',$cid,$p,$eid);self::input('period_key','ماه شمسی','','text','required placeholder="1405-07"'); ?><button type="submit" class="btn btn-primary">ثبت استهلاک و سند</button></form></section><section class="erp-card"><h3>واگذاری دارایی</h3><p>استهلاک ماه‌های قبل باید کامل باشد؛ ماه واگذاری استهلاک نمی‌گیرد. حساب مقابل برای دریافتنی یا بانک است و ثبت سند، جای برگه دریافت خزانه را نمی‌گیرد.</p><form method="post" class="erp-form"><?php self::form('module_asset_dispose',$cid,$p,$eid);self::input('doc_date','تاریخ واگذاری',Jalali::format(Jalali::today(),false),'text','required');self::input('proceeds','عواید واگذاری ('.(Ctx::unit()==='rial'?'ریال':'تومان').')','','text','required');self::select('account_id','دریافتنی یا بانک',OperationsController::accounts($cid,['asset_current']));self::select('detail_id','تفصیلی حساب مقابل',OperationsController::details($cid));self::select('result_account_id','حساب سود یا زیان متناسب نتیجه',OperationsController::accounts($cid,['other_income','other_expense'])); ?><button type="submit" class="btn btn-primary">ثبت واگذاری و سود / زیان</button></form></section><?php endif; ?>
